<?php
if(PHP_SAPI!=='cli'||!in_array('--confirmar',$argv,true))exit("Uso: php db/migrar_pagos_planilla.php --confirmar\n");require_once __DIR__.'/../config/conexion.php';if(!$conexion->query("SHOW COLUMNS FROM planilla_detalles LIKE 'monto_pagado'")->fetch()){$conexion->exec("ALTER TABLE planilla_detalles ADD COLUMN monto_pagado DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER monto_pagar,ADD COLUMN saldo_pendiente DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER monto_pagado");$conexion->exec("UPDATE planilla_detalles SET saldo_pendiente=monto_pagar");echo "Saldos de planilla agregados.\n";}$col=$conexion->query("SHOW COLUMNS FROM planilla_detalles LIKE 'estado'")->fetch();if($col&&strpos($col['Type'],"'PARCIAL'")===false){$conexion->exec("ALTER TABLE planilla_detalles MODIFY estado ENUM('CALCULADO','REVISADO','CERRADO','PARCIAL','PAGADO') NOT NULL DEFAULT 'CALCULADO'");echo "Estado parcial habilitado.\n";}if(!$conexion->query("SHOW TABLES LIKE 'pagos_planilla'")->fetch()){$conexion->exec("CREATE TABLE pagos_planilla(id_pago_planilla BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,id_planilla_detalle BIGINT UNSIGNED NOT NULL,importe DECIMAL(12,2) NOT NULL,medio_pago ENUM('EFECTIVO','TRANSFERENCIA','DEPOSITO','OTRO') NOT NULL,referencia VARCHAR(120) NULL,observacion VARCHAR(250) NULL,pagado_por BIGINT UNSIGNED NULL,pagado_en DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,estado ENUM('REGISTRADO','ANULADO') NOT NULL DEFAULT 'REGISTRADO',anulado_por BIGINT UNSIGNED NULL,anulado_en DATETIME NULL,motivo_anulacion VARCHAR(250) NULL,KEY ix_pago_planilla_detalle(id_planilla_detalle,estado),CONSTRAINT fk_pago_planilla_detalle FOREIGN KEY(id_planilla_detalle) REFERENCES planilla_detalles(id_planilla_detalle)) ENGINE=InnoDB");echo "Pagos de planilla creados.\n";}
$conexion->exec('DROP TRIGGER IF EXISTS bi_planilla_inicializar_saldo');$conexion->exec("CREATE TRIGGER bi_planilla_inicializar_saldo BEFORE INSERT ON planilla_detalles FOR EACH ROW SET NEW.monto_pagado=0,NEW.saldo_pendiente=NEW.monto_pagar");$conexion->exec('DROP TRIGGER IF EXISTS bu_planilla_recalcular_saldo');$conexion->exec("CREATE TRIGGER bu_planilla_recalcular_saldo BEFORE UPDATE ON planilla_detalles FOR EACH ROW SET NEW.saldo_pendiente=IF(NEW.estado='CALCULADO',GREATEST(0,NEW.monto_pagar-NEW.monto_pagado),NEW.saldo_pendiente)");
